+    slide.addShape(pptx.shapes.LINE, {
+      x: chartX + (chartW * i) / 5,
+      y: chartY,
+      w: 0,
+      h: chartH,
+      line: { color: theme.line, width: 1, transparency: 65 },
+    });
+  }
+
+  function mapX(val) {
+    return chartX + ((val - xMin) / (xMax - xMin)) * chartW;
+  }
+  function mapY(val) {
+    return chartY + (1 - (val - yMin) / (yMax - yMin)) * chartH;
+  }
+
+  for (const p of points) {
+    const px = mapX(p.x);
+    const py = mapY(p.y);
+    slide.addShape(pptx.shapes.OVAL, {
+      x: px - 0.07,
+      y: py - 0.07,
+      w: 0.14,
+      h: 0.14,
+      fill: { color: p.color || theme.navy },
+      line: { color: 'FFFFFF', width: 1 },
