+      h: 0.3,
+      fontFace: 'Calibri',
+      fontSize: 10,
+      color: theme.ink,
+      margin: 0,
+    });
+  }
+
+  // Axis labels
+  if (xLabel) {
+    slide.addText(xLabel, {
+      x: chartX,
+      y: y + h - 0.55,
+      w: chartW,
+      h: 0.3,
